"""Hidden behavioral tests for jo: unicode. Generated by pbkit from the gold binary."""


def test_astral_plane(run):
    r = run(args=['-a', '😀', '𝄞', '\U0010ffff'])
    assert r.stdout == b'["\xf0\x9f\x98\x80","\xf0\x9d\x84\x9e","\xf4\x8f\xbf\xbf"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_bom_value(run):
    r = run(args=['k=\ufeffx'])
    assert r.stdout == b'{"k":"\xef\xbb\xbfx"}\n'
    assert r.stderr == b''
    assert r.returncode == 0
